37	/**
38	 * Rejects creating an owner whose E.164 telephone is already used by another owner,
39	 * answering 409. Kept as its own advice so this rule stays a small, self-contained unit
40	 * rather than growing the controller or another handler.
41	 */
42	@ControllerAdvice
43	@Order(Ordered.HIGHEST_PRECEDENCE)
44	public class OwnerUniqueTelephoneAdvice extends RequestBodyAdviceAdapter {
45	
46	    private final ClinicService clinicService;
47	
48	    public OwnerUniqueTelephoneAdvice(ClinicService clinicService) {
49	        this.clinicService = clinicService;
50	    }
51	
52	    @Override
53	    public boolean supports(MethodParameter methodParameter, Type targetType,
54	                            Class<? extends HttpMessageConverter<?>> converterType) {
55	        Method method = methodParameter.getMethod();
56	        return OwnerFieldsDto.class.equals(targetType)
57	            && method != null && "addOwner".equals(method.getName());
58	    }
59	
60	    @Override
61	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
62	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
63	        String telephone = OwnerTelephoneNormalizationAdvice.toE164(((OwnerFieldsDto) body).getTelephone());
64	        boolean duplicate = clinicService.findAllOwners().stream()
65	            .map(Owner::getTelephone)
66	            .anyMatch(telephone::equals);
67	        if (duplicate) {
68	            throw new DuplicateTelephoneException();
69	        }
70	        return body;
71	    }
72	
73	    @ExceptionHandler(DuplicateTelephoneException.class)
74	    @ResponseBody
75	    public ResponseEntity<String> handleDuplicateTelephone(DuplicateTelephoneException e) {
76	        return ResponseEntity.status(HttpStatus.CONFLICT).body(e.getMessage());
77	    }
78	
79	    /** Signals a telephone already used by another owner. */
80	    static class DuplicateTelephoneException extends RuntimeException {
81	
82	        DuplicateTelephoneException() {
83	            super("telephone already in use");
84	        }
85	    }
86	}
